/**
 * gallery.js — the film lab.
 *
 * Renders the whole archive as one continuous roll of 36-frame contact
 * sheets, filters it by colour or tag, and opens a specimen-label lightbox.
 * All data is generated by tools/gallery/sync.py and embedded by the server.
 */
(function () {
    'use strict';

    const dataEl = document.getElementById('gallery-data');
    if (!dataEl) return;

    let data;
    try {
        data = JSON.parse(dataEl.textContent);
    } catch (err) {
        console.error('gallery: unreadable dataset', err);
        return;
    }

    const photos = (data.photos || []).filter(function (p) {
        return p && p.id && p.sizes;
    });
    if (!photos.length) return;

    const SHEET_SIZE = 36;
    const HUE_TOLERANCE = 18;
    const WIDTHS = { s: 240, m: 500, z: 640, c: 800, b: 1024, l: 1600, h: 2048 };

    const $ = function (sel, root) { return (root || document).querySelector(sel); };
    const pad = function (n) { return String(n).padStart(2, '0'); };

    const grid = $('#archive');
    const empty = $('#empty');
    const tagRow = $('#tag-row');
    const spectrum = $('#spectrum');
    const handle = $('#spectrum-handle');
    const readoutName = $('#spectrum-name');
    const readoutCount = $('#spectrum-count');
    const monoToggle = $('#mono-toggle');
    const clearBtn = $('#clear-filters');
    const lightbox = $('#lightbox');
    const lbImg = $('#lb-img');
    const lbLabel = $('#lb-label');
    const lbCounter = $('#lb-counter');
    const lbPrev = $('#lb-prev');
    const lbNext = $('#lb-next');

    const state = {
        hue: null,
        mono: false,
        tag: null,
    };

    let lastVisible = [];
    let lbList = [];
    let lbIndex = 0;
    let lastFocus = null;

    // ── archive ────────────────────────────────────────────────────

    function pad3(n) {
        return String(n).padStart(3, '0');
    }

    function chunk(items, size) {
        const out = [];
        for (let i = 0; i < items.length; i += size) {
            out.push(items.slice(i, i + size));
        }
        return out;
    }

    function isCameraName(title) {
        return /^_?(DSC|DSCN|IMG|PXL|GOPR|DJI|MVI|VID)[-_]?\d/i.test(title || '') ||
            /^\d{6,}$/.test(title || '') ||
            /^photo$/i.test(title || '');
    }

    // ── sheets ─────────────────────────────────────────────────────

    function sheetLabel(sheetIndex, sheetCount, start, end) {
        const label = document.createElement('div');
        label.className = 'sheet-label';

        const left = document.createElement('span');
        left.textContent = 'sheet ' + pad(sheetIndex + 1) + ' / ' + pad(sheetCount);
        left.className = 'em';

        const right = document.createElement('span');
        right.textContent = 'frames ' + pad3(start) + '–' + pad3(end);

        label.appendChild(left);
        label.appendChild(right);
        return label;
    }

    function render() {
        const sheets = chunk(photos, SHEET_SIZE);
        const section = document.createElement('section');
        section.className = 'archive';
        section.dataset.total = String(photos.length);
        section.dataset.sheets = String(sheets.length);

        const head = document.createElement('div');
        head.className = 'archive-head';

        const title = document.createElement('span');
        title.className = 'archive-title';
        title.textContent = 'the archive';

        const count = document.createElement('span');
        count.className = 'archive-count';
        count.textContent = photos.length + ' frames · ' + sheets.length + ' sheets';

        head.appendChild(title);
        head.appendChild(count);
        section.appendChild(head);

        sheets.forEach(function (slice, sheetIndex) {
            const sheet = document.createElement('div');
            sheet.className = 'sheet';

            sheet.appendChild(sheetLabel(
                sheetIndex,
                sheets.length,
                sheetIndex * SHEET_SIZE + 1,
                sheetIndex * SHEET_SIZE + slice.length
            ));

            const frames = document.createElement('div');
            frames.className = 'frames';

            slice.forEach(function (photo, i) {
                const frameNo = sheetIndex * SHEET_SIZE + i + 1;
                frames.appendChild(makeFrame(photo, frameNo, frameNo <= 8));
            });

            sheet.appendChild(frames);
            section.appendChild(sheet);
        });

        grid.innerHTML = '';
        grid.appendChild(section);
        applyFilters();
    }

    function makeFrame(photo, frameNo, eager) {
        const frame = document.createElement('button');
        frame.type = 'button';
        frame.className = 'frame';
        frame.dataset.id = photo.id;

        const img = document.createElement('img');
        img.alt = altText(photo);
        img.loading = eager ? 'eager' : 'lazy';
        img.decoding = 'async';
        if (eager) img.fetchPriority = 'high';
        img.sizes = '(max-width: 720px) 45vw, (max-width: 1100px) 30vw, 220px';
        const src = photo.sizes.z || photo.sizes.c || photo.sizes.m || photo.sizes.s;
        if (src) img.src = src;
        const set = srcset(photo);
        if (set) img.srcset = set;

        img.addEventListener('error', function () {
            frame.classList.add('is-broken');
        }, { once: true });

        const no = document.createElement('span');
        no.className = 'frame-no';
        no.textContent = pad3(frameNo);

        const label = document.createElement('span');
        label.className = 'frame-label';

        const title = document.createElement('span');
        title.className = 'fl-title';
        title.textContent = primaryLabel(photo);

        const meta = document.createElement('span');
        meta.className = 'fl-meta';
        meta.textContent = photo.width && photo.height
            ? photo.width + '×' + photo.height
            : '';

        label.appendChild(title);
        label.appendChild(meta);

        frame.appendChild(img);
        frame.appendChild(no);
        frame.appendChild(label);

        frame.setAttribute('aria-label', altText(photo) + ' — open frame ' + pad3(frameNo));
        frame.addEventListener('click', function () {
            openLightbox(photo.id);
        });

        return frame;
    }

    function primaryLabel(photo) {
        const tags = photo.tags || [];
        if (tags.length) return tags.slice(0, 2).join(' · ');
        if (photo.caption) return photo.caption;
        if (photo.title && !isCameraName(photo.title)) return photo.title;
        return 'untitled';
    }

    function altText(photo) {
        if (photo.alt) return photo.alt;
        if (photo.caption) return photo.caption;
        const tags = photo.tags || [];
        if (tags.length) return 'Photograph — ' + tags.join(', ');
        return 'Photograph';
    }

    function srcset(photo) {
        return Object.keys(WIDTHS)
            .filter(function (key) { return photo.sizes[key]; })
            .map(function (key) { return photo.sizes[key] + ' ' + WIDTHS[key] + 'w'; })
            .join(', ');
    }

    function bestImage(photo, large) {
        const order = large
            ? ['l', 'b', 'h', 'c', 'z', 'm']
            : ['b', 'c', 'z', 'm', 's'];
        for (let i = 0; i < order.length; i++) {
            if (photo.sizes[order[i]]) return photo.sizes[order[i]];
        }
        return '';
    }

    // ── filtering ──────────────────────────────────────────────────

    function matches(photo) {
        const tags = photo.tags || [];
        if (state.tag === '__untagged') {
            if (tags.length) return false;
        } else if (state.tag && tags.indexOf(state.tag) === -1) {
            return false;
        }

        if (state.mono) {
            return (photo.sat == null ? 1 : photo.sat) < 0.15;
        }

        if (state.hue !== null) {
            if ((photo.sat == null ? 0 : photo.sat) < 0.12) return false;
            if (photo.hue == null) return false;
            const diff = Math.abs(photo.hue - state.hue);
            return Math.min(diff, 360 - diff) <= HUE_TOLERANCE;
        }

        return true;
    }

    function applyFilters() {
        const byId = new Map(photos.map(function (p) { return [p.id, p]; }));
        const visible = [];
        const visibleBySheet = new Map();

        grid.querySelectorAll('.frame').forEach(function (el) {
            const photo = byId.get(el.dataset.id);
            if (!photo) return;
            const ok = matches(photo);
            el.classList.toggle('is-hidden', !ok);
            if (ok) {
                visible.push(photo);
                const sheet = el.closest('.sheet');
                if (sheet) {
                    visibleBySheet.set(sheet, (visibleBySheet.get(sheet) || 0) + 1);
                }
            }
        });

        const archive = grid.querySelector('.archive');
        if (archive) {
            const total = Number(archive.dataset.total || photos.length);
            const sheets = Number(archive.dataset.sheets || 0);
            const count = archive.querySelector('.archive-count');
            if (count) {
                count.textContent = visible.length === total
                    ? total + ' frames · ' + sheets + ' sheets'
                    : visible.length + ' / ' + total + ' frames';
            }
        }

        grid.querySelectorAll('.sheet').forEach(function (sheet) {
            const shown = visibleBySheet.get(sheet) || 0;
            sheet.classList.toggle('is-empty', shown === 0);
        });

        lastVisible = visible;
        empty.hidden = visible.length !== 0;

        const filtering = state.hue !== null || state.mono || state.tag !== null;
        clearBtn.hidden = !filtering;
        monoToggle.setAttribute('aria-pressed', String(state.mono));

        if (state.hue !== null) {
            readoutName.textContent = hueName(state.hue) + ' · ' + Math.round(state.hue) + '°';
            readoutCount.textContent = visible.length + (visible.length === 1 ? ' frame' : ' frames');
        } else if (state.mono) {
            readoutName.textContent = 'mono';
            readoutCount.textContent = visible.length + (visible.length === 1 ? ' frame' : ' frames');
        } else if (state.tag) {
            readoutName.textContent = state.tag === '__untagged' ? 'untagged' : state.tag;
            readoutCount.textContent = visible.length + (visible.length === 1 ? ' frame' : ' frames');
        } else {
            readoutName.textContent = 'all light';
            readoutCount.textContent = photos.length + ' frames';
        }

        spectrum.setAttribute(
            'aria-valuetext',
            (state.hue === null ? 'all colours' : hueName(state.hue) + ' ' + Math.round(state.hue) + ' degrees') +
            ', ' + visible.length + ' frames'
        );
    }

    function hueName(hue) {
        const names = [
            [12, 'red'], [32, 'rust'], [50, 'amber'], [72, 'olive'],
            [105, 'moss'], [145, 'green'], [172, 'pine'], [195, 'teal'],
            [218, 'cyan'], [242, 'steel'], [268, 'indigo'], [298, 'violet'],
            [325, 'magenta'], [348, 'rose'], [361, 'red'],
        ];
        for (let i = 0; i < names.length; i++) {
            if (hue < names[i][0]) return names[i][1];
        }
        return 'red';
    }

    // ── spectrum control ───────────────────────────────────────────

    function setHue(hue) {
        const clamped = Math.max(0, Math.min(359.9, hue));
        state.hue = clamped;
        state.mono = false;
        spectrum.classList.add('has-hue');
        spectrum.setAttribute('aria-valuenow', String(Math.round(clamped)));
        handle.style.left = (clamped / 360 * 100) + '%';
        handle.style.background = 'hsl(' + clamped + ' 58% 58%)';
        applyFilters();
    }

    function clearHue() {
        state.hue = null;
        spectrum.classList.remove('has-hue');
        spectrum.setAttribute('aria-valuenow', '0');
        handle.style.left = '0%';
        applyFilters();
    }

    function hueFromEvent(event) {
        const rect = spectrum.getBoundingClientRect();
        const x = Math.max(0, Math.min(rect.width, event.clientX - rect.left));
        return (x / rect.width) * 360;
    }

    let dragging = false;

    spectrum.addEventListener('pointerdown', function (event) {
        if (event.button !== undefined && event.button !== 0) return;
        dragging = true;
        spectrum.setPointerCapture(event.pointerId);
        setHue(hueFromEvent(event));
        event.preventDefault();
    });

    spectrum.addEventListener('pointermove', function (event) {
        if (!dragging) return;
        setHue(hueFromEvent(event));
    });

    function stopDrag(event) {
        if (!dragging) return;
        dragging = false;
        if (spectrum.hasPointerCapture && spectrum.hasPointerCapture(event.pointerId)) {
            spectrum.releasePointerCapture(event.pointerId);
        }
    }
    spectrum.addEventListener('pointerup', stopDrag);
    spectrum.addEventListener('pointercancel', stopDrag);

    spectrum.addEventListener('keydown', function (event) {
        const current = state.hue === null ? 0 : state.hue;
        const step = event.shiftKey ? 10 : 2;
        let next = null;

        if (event.key === 'ArrowLeft' || event.key === 'ArrowDown') next = current - step;
        else if (event.key === 'ArrowRight' || event.key === 'ArrowUp') next = current + step;
        else if (event.key === 'Home') next = 0;
        else if (event.key === 'End') next = 359.9;
        else if (event.key === 'Escape' || event.key === 'Backspace') {
            clearHue();
            event.preventDefault();
            return;
        }

        if (next !== null) {
            setHue((next + 360) % 360);
            event.preventDefault();
        }
    });

    monoToggle.addEventListener('click', function () {
        state.mono = !state.mono;
        if (state.mono) clearHueSilently();
        applyFilters();
    });

    function clearHueSilently() {
        state.hue = null;
        spectrum.classList.remove('has-hue');
        spectrum.setAttribute('aria-valuenow', '0');
        handle.style.left = '0%';
    }

    clearBtn.addEventListener('click', resetFilters);

    function resetFilters() {
        state.tag = null;
        state.mono = false;
        clearHueSilently();
        tagRow.querySelectorAll('.chip').forEach(function (chip) {
            chip.setAttribute('aria-pressed', String(chip.dataset.tag === ''));
        });
        applyFilters();
    }

    // ── tags ───────────────────────────────────────────────────────

    function buildTags() {
        const counts = new Map();
        photos.forEach(function (photo) {
            (photo.tags || []).forEach(function (tag) {
                counts.set(tag, (counts.get(tag) || 0) + 1);
            });
        });

        const sorted = Array.from(counts.entries()).sort(function (a, b) {
            return b[1] - a[1] || a[0].localeCompare(b[0]);
        });

        const fragment = document.createDocumentFragment();

        const all = document.createElement('button');
        all.type = 'button';
        all.className = 'chip';
        all.dataset.tag = '';
        all.setAttribute('aria-pressed', 'true');
        all.innerHTML = 'all <span class="n">' + photos.length + '</span>';
        all.addEventListener('click', function () {
            state.tag = null;
            tagRow.querySelectorAll('.chip').forEach(function (chip) {
                chip.setAttribute('aria-pressed', String(chip.dataset.tag === ''));
            });
            applyFilters();
        });
        fragment.appendChild(all);

        const untagged = photos.filter(function (photo) {
            return !(photo.tags || []).length;
        }).length;

        if (untagged) {
            const chip = document.createElement('button');
            chip.type = 'button';
            chip.className = 'chip';
            chip.dataset.tag = '__untagged';
            chip.setAttribute('aria-pressed', 'false');
            chip.innerHTML = 'untagged <span class="n">' + untagged + '</span>';
            chip.addEventListener('click', function () {
                state.tag = state.tag === '__untagged' ? null : '__untagged';
                tagRow.querySelectorAll('.chip').forEach(function (other) {
                    other.setAttribute('aria-pressed', String(
                        other.dataset.tag === (state.tag || '')
                    ));
                });
                applyFilters();
            });
            fragment.appendChild(chip);
        }

        sorted.forEach(function (entry) {
            const tag = entry[0];
            const chip = document.createElement('button');
            chip.type = 'button';
            chip.className = 'chip';
            chip.dataset.tag = tag;
            chip.setAttribute('aria-pressed', 'false');
            chip.innerHTML = escapeHtml(tag) + ' <span class="n">' + entry[1] + '</span>';
            chip.addEventListener('click', function () {
                state.tag = state.tag === tag ? null : tag;
                tagRow.querySelectorAll('.chip').forEach(function (other) {
                    other.setAttribute('aria-pressed', String(
                        other.dataset.tag === (state.tag || '')
                    ));
                });
                applyFilters();
            });
            fragment.appendChild(chip);
        });

        tagRow.appendChild(fragment);
    }

    function escapeHtml(value) {
        return String(value)
            .replace(/&/g, '&amp;')
            .replace(/</g, '&lt;')
            .replace(/>/g, '&gt;')
            .replace(/"/g, '&quot;');
    }

    // ── lightbox ───────────────────────────────────────────────────

    function openLightbox(id) {
        const photo = photos.find(function (p) { return p.id === id; });
        if (!photo) return;

        if (!lastVisible.some(function (p) { return p.id === id; })) {
            resetFilters();
        }

        lbList = lastVisible.length ? lastVisible.slice() : [photo];
        lbIndex = Math.max(0, lbList.findIndex(function (p) { return p.id === id; }));
        lastFocus = document.activeElement;

        showLightbox();
        lightbox.hidden = false;
        document.body.classList.add('lb-open');
        $('#lb-close').focus({ preventScroll: true });
        syncHash(photo.id);
    }

    function showLightbox() {
        const photo = lbList[lbIndex];
        if (!photo) return;

        const src = bestImage(photo, true);
        const set = srcset(photo);

        lbImg.src = src;
        if (set) {
            lbImg.srcset = set;
            lbImg.sizes = '(max-width: 900px) 100vw, 70vw';
        } else {
            lbImg.removeAttribute('srcset');
        }
        lbImg.alt = altText(photo);

        renderLabel(photo);

        lbCounter.textContent = pad(lbIndex + 1) + ' / ' + pad(lbList.length);
        lbPrev.disabled = lbList.length < 2;
        lbNext.disabled = lbList.length < 2;

        preload(lbIndex - 1);
        preload(lbIndex + 1);
    }

    function preload(index) {
        if (index < 0 || index >= lbList.length) return;
        const photo = lbList[index];
        const src = bestImage(photo, true);
        if (src) {
            const img = new Image();
            img.src = src;
        }
    }

    function renderLabel(photo) {
        lbLabel.innerHTML = '';

        const place = frameOf(photo);

        const heading = document.createElement('div');
        heading.className = 'lb-frame';
        heading.innerHTML = place
            ? 'frame <span class="hash">' + pad3(place.frame) + '</span> / ' + pad3(photos.length) +
              ' · sheet ' + pad(place.sheet) + ' / ' + pad(place.sheets)
            : 'frame';
        lbLabel.appendChild(heading);

        const tags = photo.tags || [];
        if (tags.length) {
            const tagWrap = document.createElement('div');
            tagWrap.className = 'lb-tags';
            tags.forEach(function (tag) {
                const span = document.createElement('span');
                span.className = 'lb-tag';
                span.textContent = tag;
                tagWrap.appendChild(span);
            });
            lbLabel.appendChild(tagWrap);
        }

        const fields = document.createElement('div');
        fields.className = 'lb-fields';
        addField(fields, 'file', photo.title && !isCameraName(photo.title) ? photo.title : null);
        addField(fields, 'size', photo.width && photo.height ? photo.width + ' × ' + photo.height : null);
        addField(fields, 'type', photo.type && photo.type !== 'photography' ? photo.type : null);
        if (photo.exif) {
            addField(fields, 'camera', photo.exif.camera);
            addField(fields, 'lens', photo.exif.lens);
            addField(fields, 'focal', photo.exif.focal);
            addField(fields, 'aperture', photo.exif.aperture);
            addField(fields, 'shutter', photo.exif.shutter);
            addField(fields, 'iso', photo.exif.iso);
        }
        if (fields.children.length) lbLabel.appendChild(fields);

        const palette = photo.palette || [];
        if (palette.length) {
            const wrap = document.createElement('div');
            wrap.className = 'lb-palette';
            palette.forEach(function (colour) {
                const swatch = document.createElement('span');
                swatch.className = 'lb-swatch';
                swatch.style.background = colour;
                swatch.title = colour;
                wrap.appendChild(swatch);
            });
            lbLabel.appendChild(wrap);
        }

        if (photo.caption) {
            const caption = document.createElement('div');
            caption.textContent = photo.caption;
            lbLabel.appendChild(caption);
        }

        const link = document.createElement('a');
        link.className = 'lb-link';
        link.href = photo.url || ('https://www.flickr.com/photos/' + (data.owner || '') + '/' + photo.id + '/');
        link.target = '_blank';
        link.rel = 'noopener';
        link.textContent = 'view on flickr ↗';
        lbLabel.appendChild(link);
    }

    function addField(root, name, value) {
        if (!value) return;
        const row = document.createElement('div');
        const key = document.createElement('span');
        key.textContent = name;
        const val = document.createElement('b');
        val.textContent = value;
        row.appendChild(key);
        row.appendChild(val);
        root.appendChild(row);
    }

    function frameOf(photo) {
        const index = photos.findIndex(function (p) { return p.id === photo.id; });
        if (index === -1) return null;
        return {
            frame: index + 1,
            sheet: Math.floor(index / SHEET_SIZE) + 1,
            sheets: Math.ceil(photos.length / SHEET_SIZE),
        };
    }

    function closeLightbox() {
        lightbox.hidden = true;
        document.body.classList.remove('lb-open');
        lbImg.removeAttribute('src');
        lbImg.removeAttribute('srcset');
        clearHash();
        if (lastFocus && lastFocus.focus) lastFocus.focus({ preventScroll: true });
    }

    function step(delta) {
        if (lbList.length < 2) return;
        lbIndex = (lbIndex + delta + lbList.length) % lbList.length;
        showLightbox();
        const photo = lbList[lbIndex];
        if (photo) syncHash(photo.id);
    }

    function syncHash(id) {
        const next = '#p/' + id;
        if (location.hash !== next) {
            history.replaceState(null, '', location.pathname + location.search + next);
        }
    }

    function clearHash() {
        if (location.hash) {
            history.replaceState(null, '', location.pathname + location.search);
        }
    }

    lbPrev.addEventListener('click', function () { step(-1); });
    lbNext.addEventListener('click', function () { step(1); });
    $('#lb-close').addEventListener('click', closeLightbox);
    lightbox.querySelectorAll('[data-close]').forEach(function (el) {
        el.addEventListener('click', closeLightbox);
    });

    document.addEventListener('keydown', function (event) {
        if (lightbox.hidden) return;
        if (event.key === 'Escape') {
            closeLightbox();
            event.preventDefault();
        } else if (event.key === 'ArrowLeft') {
            step(-1);
            event.preventDefault();
        } else if (event.key === 'ArrowRight') {
            step(1);
            event.preventDefault();
        } else if (event.key === 'Tab') {
            const focusables = Array.from(lightbox.querySelectorAll('button:not([disabled]), a[href]'));
            if (!focusables.length) return;
            const first = focusables[0];
            const last = focusables[focusables.length - 1];
            if (event.shiftKey && document.activeElement === first) {
                last.focus();
                event.preventDefault();
            } else if (!event.shiftKey && document.activeElement === last) {
                first.focus();
                event.preventDefault();
            }
        }
    });

    window.addEventListener('hashchange', function () {
        const match = location.hash.match(/^#p\/(\d+)$/);
        if (match) {
            if (lightbox.hidden) openLightbox(match[1]);
        } else if (!lightbox.hidden) {
            closeLightbox();
        }
    });

    // ── boot ───────────────────────────────────────────────────────

    $('#frame-count').textContent = photos.length;
    $('#foot-count').textContent = photos.length + ' frames · ' +
        Math.ceil(photos.length / SHEET_SIZE) + ' sheets';
    document.title = document.title.replace('Gallery', 'Gallery · ' + photos.length + ' frames');

    render();
    buildTags();
    applyFilters();

    const deepLink = location.hash.match(/^#p\/(\d+)$/);
    if (deepLink) {
        resetFilters();
        requestAnimationFrame(function () {
            openLightbox(deepLink[1]);
        });
    }
})();
